import {
  createFileRoute,
  Outlet,
  useLocation,
  useNavigate
} from '@tanstack/react-router';
import { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Flex, Button, Modal, useToast } from '@docs-front/ui';
import { useModal } from '@/hooks/useModal';
import { useQuery } from '@tanstack/react-query';
import { X } from 'lucide-react';
import type { Theme } from '@docshunt/docs-editor-wasm';

import { getAllTemplateFilesByTypeQueryOptions } from '@/query/options/products';
import { postVisualSuggestions } from '@/api/products/mutation';
import i18n from '@/i18n';
import {
  getAIReviewerTotalLimit,
  getIdeaModeValidationMessage,
  getTextLength,
  MAX_IDEA_MODE_LENGTH
} from '@/schema/main/detailInput';
import {
  deleteFileFromIndexedDB,
  getFileFromIndexedDB,
  saveFileToIndexedDB,
  type FileMetadata
} from '@/utils/file/fileStorage';
import { InstantStepper } from '@/routes/_authenticated/start/-components/InstantStepper/InstantStepper';
import { StartFlowProvider } from '@/routes/_authenticated/start/-startFlow.context';
import {
  clearStartFunnelSession,
  normalizeStartFunnelSessionStorage,
  readStartFunnelSession,
  writeStartFunnelSession
} from '@/routes/_authenticated/start/-funnelStorage';
import {
  DEFAULT_START_FUNNEL_CONTEXT,
  DEFAULT_START_PROMPT_STATE,
  type StartFunnelSession,
  type StartSelectedDocumentInfo,
  type StartStepKey
} from '@/routes/_authenticated/start/-startFlow.types';
import {
  getStartAIQuestions,
  getStartAIReviewerTotalLength
} from '@/routes/_authenticated/start/-components/steps/Step2Prompt.utils';
import {
  sortDraftTemplateOptions,
  toDraftTemplateOption,
  type DraftTemplateOption
} from '@/routes/_authenticated/start/-components/steps/draftTemplateProfile';
import {
  StyledStartContainer,
  StyledContentArea,
  StyledStepContent,
  StyledFooter,
  StyledFooterInner,
  StyledModalOverlay,
  StyledModalBox,
  StyledModalHeader,
  StyledModalTitle,
  StyledModalClose,
  StyledModalDesc,
  StyledModalFooter,
  StyledBtnOutlined,
  StyledBtnWarning,
  StyledLoadingOverlay,
  StyledLoadingPopup,
  StyledLoadingSpinnerRing,
  StyledLoadingSteps,
  StyledLoadingStep,
  StyledLoadingDot
} from '@/routes/_authenticated/start/-route.style';
import type { ImageItem } from '@/routes/_authenticated/start/-components/steps/Step4ImageSelect';

const TEMPLATE_PATH = '/start/template';
const PROMPT_PATH = '/start/prompt';
const UPLOAD_PATH = '/start/upload';
const VISUAL_SUGGESTIONS_PATH = '/start/visual-suggestions';
const SETTINGS_PATH = '/start/settings';
const GENERATE_PATH = '/start/generate';

const LOADING_STEPS = [
  '양식 분석 중...',
  '자료 분석 중...',
  '이미지 리스트 생성 중...',
  '완료'
];

const getCurrentStepKey = (path: string): StartStepKey | null => {
  if (path.startsWith(GENERATE_PATH)) return 'generate';
  if (path.startsWith(SETTINGS_PATH)) return 'settings';
  if (path.startsWith(VISUAL_SUGGESTIONS_PATH)) return 'visual-suggestions';
  if (path.startsWith(UPLOAD_PATH)) return 'upload';
  if (path.startsWith(PROMPT_PATH)) return 'prompt';
  if (path.startsWith(TEMPLATE_PATH)) return 'template';
  return null;
};

const getCurrentStepNumber = (path: string) => {
  const stepKey = getCurrentStepKey(path);

  switch (stepKey) {
    case 'prompt':
      return 2;
    case 'upload':
      return 3;
    case 'visual-suggestions':
      return 4;
    case 'settings':
      return 5;
    case 'generate':
      return 6;
    case 'template':
    default:
      return 1;
  }
};

const getSavedInitialSession = (): StartFunnelSession | null =>
  readStartFunnelSession();

export const Route = createFileRoute('/_authenticated/start')({
  component: RouteComponent
});

function RouteComponent() {
  const toast = useToast();
  const modal = useModal();
  const navigate = useNavigate();
  const location = useLocation();
  const currentPath = location.pathname;
  const contentRef = useRef<HTMLDivElement>(null);
  const loadingTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const referenceFilesPersistQueueRef = useRef<Promise<void>>(
    Promise.resolve()
  );
  const previousStepKeyRef = useRef<StartStepKey | null>(null);
  const initialSession = useMemo(getSavedInitialSession, []);
  const initialContext =
    initialSession?.context ?? DEFAULT_START_FUNNEL_CONTEXT;

  const [selectedDraftTemplate, setSelectedDraftTemplate] =
    useState<DraftTemplateOption | null>(
      initialContext.selectedDraftTemplate ?? null
    );
  const [prompt, setPrompt] = useState(initialContext.prompt ?? '');
  const [promptState, setPromptState] = useState(
    initialContext.promptState ?? DEFAULT_START_PROMPT_STATE
  );
  const [hasUpload, setHasUpload] = useState(
    initialContext.hasUpload ||
      (initialContext.referenceFileIds?.length ?? 0) > 0
  );
  const [selectedDocument, setSelectedDocument] =
    useState<StartSelectedDocumentInfo | null>(
      initialContext.selectedDocument ?? null
    );
  const [referenceFileIds, setReferenceFileIds] = useState<string[]>(
    initialContext.referenceFileIds ?? []
  );
  const [referenceFiles, setReferenceFilesState] = useState<File[]>([]);
  const referenceFilesStateRef = useRef<File[]>([]);
  const referenceFileIdsRef = useRef<string[]>(
    initialContext.referenceFileIds ?? []
  );
  const [isReferenceFilesProcessing, setIsReferenceFilesProcessing] =
    useState(false);
  const [images, setImages] = useState<ImageItem[]>(
    initialContext.images ?? []
  );
  const [hasGeneratedSuggestions, setHasGeneratedSuggestions] = useState(
    initialContext.hasGeneratedSuggestions ?? false
  );
  const [theme, setTheme] = useState<Theme | undefined>(initialContext.theme);
  const [exportedProductId, setExportedProductId] = useState<string | null>(
    initialContext.exportedProductId ?? null
  );
  const [generateStartToken, setGenerateStartToken] = useState(0);

  const [showImageResetWarning, setShowImageResetWarning] = useState(false);
  const [showLoadingPopup, setShowLoadingPopup] = useState(false);
  const [loadingStep, setLoadingStep] = useState(0);
  const [loadingError, setLoadingError] = useState(false);

  const {
    data: draftTemplateFiles = [],
    isLoading: isDraftTemplatesLoading,
    isError: isDraftTemplatesError,
    refetch: refetchDraftTemplates
  } = useQuery(getAllTemplateFilesByTypeQueryOptions('DRAFT_TEMPLATE'));

  const draftTemplates = useMemo(
    () => sortDraftTemplateOptions(draftTemplateFiles.map(toDraftTemplateOption)),
    [draftTemplateFiles]
  );
  const templateName = selectedDraftTemplate?.name ?? '양식';
  const selectedTemplateFileId = selectedDraftTemplate?.id ?? null;
  const selectedPromptProfile =
    selectedDraftTemplate?.promptProfile ?? 'business_plan';
  const currentStep = getCurrentStepNumber(currentPath);
  const currentStepKey = getCurrentStepKey(currentPath);
  const isTemplateRoute = currentPath.startsWith(TEMPLATE_PATH);

  useEffect(() => {
    normalizeStartFunnelSessionStorage();
  }, []);

  const scrollToTop = useCallback(() => {
    contentRef.current?.scrollTo(0, 0);
  }, []);

  const clearLoadingTimer = useCallback(() => {
    if (loadingTimerRef.current) {
      clearInterval(loadingTimerRef.current);
      loadingTimerRef.current = null;
    }
  }, []);

  useEffect(() => {
    scrollToTop();
  }, [currentPath, scrollToTop]);

  useEffect(() => {
    return () => {
      clearLoadingTimer();
    };
  }, [clearLoadingTimer]);

  useEffect(() => {
    const restoreFiles = async () => {
      if (referenceFileIdsRef.current.length === 0) {
        referenceFilesStateRef.current = [];
        setReferenceFilesState([]);
        return;
      }

      const files: File[] = [];
      for (const fileId of referenceFileIdsRef.current) {
        const result = await getFileFromIndexedDB(fileId);
        if (result) {
          files.push(result.file);
        }
      }

      referenceFilesStateRef.current = files;
      setReferenceFilesState(files);
      setHasUpload(files.length > 0);
    };

    void restoreFiles();
  }, []);

  useEffect(() => {
    referenceFilesStateRef.current = referenceFiles;
  }, [referenceFiles]);

  const runReferenceFilesPersistence = useCallback(
    (task: () => Promise<void>) => {
      const nextTask = referenceFilesPersistQueueRef.current
        .catch(() => undefined)
        .then(task);
      referenceFilesPersistQueueRef.current = nextTask;
      return nextTask;
    },
    []
  );

  const persistReferenceFiles = useCallback(
    async (files: File[]) => {
      const previousFiles = referenceFilesStateRef.current;

      referenceFilesStateRef.current = files;
      setReferenceFilesState(files);
      setHasUpload(files.length > 0);

      try {
        await runReferenceFilesPersistence(async () => {
          const previousFileIds = referenceFileIdsRef.current;
          const newFileIds: string[] = [];

          try {
            for (const file of files) {
              const metadata: FileMetadata = {
                name: file.name,
                size: file.size,
                type: file.type,
                lastModified: file.lastModified,
                isBlob: true
              };
              const fileId = await saveFileToIndexedDB(file, metadata);
              newFileIds.push(fileId);
            }
          } catch (error) {
            await Promise.allSettled(
              newFileIds.map(async (fileId) => {
                await deleteFileFromIndexedDB(fileId);
              })
            );
            throw error;
          }

          referenceFileIdsRef.current = newFileIds;
          setReferenceFileIds(newFileIds);

          await Promise.allSettled(
            previousFileIds.map(async (fileId) => {
              await deleteFileFromIndexedDB(fileId);
            })
          );
        });
      } catch (error) {
        referenceFilesStateRef.current = previousFiles;
        setReferenceFilesState(previousFiles);
        setHasUpload(previousFiles.length > 0);
        throw error;
      }
    },
    [runReferenceFilesPersistence]
  );

  const deleteStoredReferenceFiles = useCallback(async () => {
    referenceFilesStateRef.current = [];
    setReferenceFilesState([]);
    setHasUpload(false);
    await runReferenceFilesPersistence(async () => {
      for (const fileId of referenceFileIdsRef.current) {
        await deleteFileFromIndexedDB(fileId);
      }
      referenceFileIdsRef.current = [];
      setReferenceFileIds([]);
    });
  }, [runReferenceFilesPersistence]);

  const clearCompletedFlow = useCallback(async () => {
    await deleteStoredReferenceFiles();
    clearStartFunnelSession();
  }, [deleteStoredReferenceFiles]);

  const resetFlowState = useCallback(
    ({
      preserveTemplateSelection = false
    }: {
      preserveTemplateSelection?: boolean;
    } = {}) => {
      if (!preserveTemplateSelection) {
        setSelectedDraftTemplate(null);
      }
      setPrompt('');
      setPromptState(DEFAULT_START_PROMPT_STATE);
      setSelectedDocument(null);
      setImages([]);
      setHasGeneratedSuggestions(false);
      setTheme(undefined);
      setExportedProductId(null);
      setGenerateStartToken(0);
      setShowImageResetWarning(false);
      setShowLoadingPopup(false);
      setLoadingError(false);
      setLoadingStep(0);
      setIsReferenceFilesProcessing(false);
    },
    []
  );

  const resetFromTemplateEntry = useCallback(async () => {
    resetFlowState();
    await deleteStoredReferenceFiles();
  }, [deleteStoredReferenceFiles, resetFlowState]);

  const resetFlow = useCallback(async () => {
    await deleteStoredReferenceFiles();
    clearStartFunnelSession();
    resetFlowState();
    navigate({ to: TEMPLATE_PATH });
  }, [deleteStoredReferenceFiles, navigate, resetFlowState]);

  useEffect(() => {
    if (!currentStepKey) return;

    writeStartFunnelSession({
      step: currentStepKey,
      context: {
        selectedDraftTemplate,
        prompt,
        promptState,
        hasUpload,
        selectedDocument,
        referenceFileIds,
        hasGeneratedSuggestions,
        images,
        theme,
        exportedProductId
      }
    });
  }, [
    currentStepKey,
    exportedProductId,
    hasGeneratedSuggestions,
    hasUpload,
    images,
    prompt,
    promptState,
    referenceFileIds,
    selectedDocument,
    selectedDraftTemplate,
    theme
  ]);

  useEffect(() => {
    const previousStepKey = previousStepKeyRef.current;

    if (currentStepKey === 'template' && previousStepKey !== 'template') {
      void resetFromTemplateEntry();
    }

    previousStepKeyRef.current = currentStepKey;
  }, [currentStepKey, resetFromTemplateEntry]);

  const callSuggestionsApi = useCallback(async () => {
    if (!selectedTemplateFileId) return;

    clearLoadingTimer();
    setShowLoadingPopup(true);
    setLoadingStep(0);
    setLoadingError(false);

    let step = 0;
    loadingTimerRef.current = setInterval(
      () => {
        step += 1;
        if (step <= 1) setLoadingStep(step);
        if (step >= 2 && loadingTimerRef.current) {
          clearInterval(loadingTimerRef.current);
          loadingTimerRef.current = null;
        }
      },
      1500 + Math.random() * 2000
    );

    try {
      const result = await postVisualSuggestions({
        contents: {
          templateFileId: selectedTemplateFileId,
          userPrompt: prompt,
          productContents:
            selectedDocument?.type === 'draftProduct'
              ? selectedDocument.productContents
              : undefined,
          exportProductFileId:
            selectedDocument?.type === 'export' ||
            selectedDocument?.type === 'draftExport'
              ? selectedDocument.id
              : undefined
        },
        referenceFiles: referenceFiles.length > 0 ? referenceFiles : undefined
      });

      const mapped: ImageItem[] = result.map((item) => ({
        title: item.name,
        prompt: item.info,
        position: item.position,
        genBy: 'ai',
        checked: true
      }));

      clearLoadingTimer();
      setImages(mapped);
      setHasGeneratedSuggestions(true);
      setLoadingStep(2);
      await new Promise((resolve) => setTimeout(resolve, 500));
      setLoadingStep(3);
      await new Promise((resolve) => setTimeout(resolve, 400));
      setShowLoadingPopup(false);
      navigate({ to: VISUAL_SUGGESTIONS_PATH });
    } catch {
      clearLoadingTimer();
      setLoadingError(true);
    }
  }, [
    clearLoadingTimer,
    navigate,
    prompt,
    referenceFiles,
    selectedDocument,
    selectedTemplateFileId
  ]);

  const handleRetry = useCallback(() => {
    void callSuggestionsApi();
  }, [callSuggestionsApi]);

  const canGoNext = useCallback((): boolean => {
    switch (currentStepKey) {
      case 'template':
        return selectedTemplateFileId !== null;
      case 'prompt':
        return prompt.trim() !== '';
      case 'upload':
        return (
          !isReferenceFilesProcessing &&
          (prompt.trim() !== '' || hasUpload || selectedDocument !== null)
        );
      case 'visual-suggestions':
      case 'settings':
        return true;
      default:
        return true;
    }
  }, [
    currentStepKey,
    hasUpload,
    isReferenceFilesProcessing,
    prompt,
    selectedDocument,
    selectedTemplateFileId
  ]);

  const goPrev = useCallback(() => {
    if (currentStepKey === 'prompt') {
      void resetFromTemplateEntry();
      navigate({ to: TEMPLATE_PATH });
      return;
    }

    if (currentStepKey === 'upload') {
      navigate({ to: PROMPT_PATH });
      return;
    }

    if (currentStepKey === 'visual-suggestions') {
      const hasPrompts = images.some((img) => img.prompt.trim() !== '');
      if (hasPrompts) {
        setShowImageResetWarning(true);
        return;
      }
      setImages([]);
      setHasGeneratedSuggestions(false);
      navigate({ to: UPLOAD_PATH });
      return;
    }

    if (currentStepKey === 'settings') {
      navigate({ to: VISUAL_SUGGESTIONS_PATH });
    }
  }, [currentStepKey, images, navigate, resetFromTemplateEntry]);

  const confirmImageReset = useCallback(() => {
    setImages([]);
    setHasGeneratedSuggestions(false);
    setShowImageResetWarning(false);
    navigate({ to: UPLOAD_PATH });
  }, [navigate]);

  const goNext = useCallback(() => {
    if (currentStepKey === 'template') {
      if (!selectedTemplateFileId) return;
      navigate({ to: PROMPT_PATH });
      return;
    }

    if (currentStepKey === 'prompt') {
      if (promptState.activeTab === 'idea') {
        if (getTextLength(promptState.ideaText) > MAX_IDEA_MODE_LENGTH) {
          toast.open({
            content: getIdeaModeValidationMessage(),
            duration: 3000
          });
          return;
        }
      } else {
        const aiReviewerTotalLength = getStartAIReviewerTotalLength({
          answers: promptState.aiAnswers,
          promptProfile: selectedPromptProfile
        });
        const aiReviewerTotalLimit = getAIReviewerTotalLimit(
          getStartAIQuestions(selectedPromptProfile).length
        );

        if (aiReviewerTotalLength > aiReviewerTotalLimit) {
          toast.open({
            content: i18n.t(
              'common:form.validation.maximumLengthAiReviewerTotal',
              {
                count: aiReviewerTotalLimit
              }
            ),
            duration: 3000
          });
          return;
        }
      }

      navigate({ to: UPLOAD_PATH });
      return;
    }

    if (currentStepKey === 'upload') {
      if (isReferenceFilesProcessing) return;

      const step2Valid = prompt.trim() !== '';
      const step3Valid = hasUpload || selectedDocument !== null;

      if (!step2Valid && !step3Valid) {
        toast.open({
          content: '프롬프트 입력 또는 자료 업로드 중 하나는 진행해야 합니다.',
          duration: 3000
        });
        return;
      }

      void callSuggestionsApi();
      return;
    }

    if (currentStepKey === 'visual-suggestions') {
      navigate({ to: SETTINGS_PATH });
      return;
    }

    if (currentStepKey === 'settings') {
      setGenerateStartToken((prev) => prev + 1);
      navigate({ to: GENERATE_PATH });
    }
  }, [
    callSuggestionsApi,
    currentStepKey,
    hasUpload,
    isReferenceFilesProcessing,
    navigate,
    prompt,
    promptState.activeTab,
    promptState.aiAnswers,
    promptState.ideaText,
    selectedDocument,
    selectedPromptProfile,
    selectedTemplateFileId,
    toast
  ]);

  const handleNextWithValidation = useCallback(() => {
    if (currentStepKey === 'prompt' && prompt.trim() === '') {
      toast.open({
        content: '프롬프트를 입력하거나 건너뛰기를 선택해주세요.',
        duration: 3000
      });
      return;
    }

    if (currentStepKey === 'visual-suggestions') {
      const selectedImages = images.filter((img) => img.checked);
      const hasEmptyField =
        selectedImages.length > 0 &&
        selectedImages.some((img) => !img.title.trim() || !img.prompt.trim());

      if (hasEmptyField) {
        modal.openModal(({ isOpen, onClose }) => (
          <Modal isOpen={isOpen} onClose={onClose}>
            <Modal.Header title="입력되지 않은 항목이 있습니다" />
            <Modal.Body>
              선택된 이미지의 제목과 생성 프롬프트를 모두 입력해주세요.
            </Modal.Body>
            <Modal.Footer>
              <Modal.ConfirmButton onClick={onClose}>확인</Modal.ConfirmButton>
            </Modal.Footer>
          </Modal>
        ));
        return;
      }
    }

    goNext();
  }, [currentStepKey, goNext, images, modal, prompt, toast]);

  const contextValue = useMemo(
    () => ({
      draftTemplates,
      isDraftTemplatesLoading,
      isDraftTemplatesError,
      refetchDraftTemplates: async () => refetchDraftTemplates(),
      selectedDraftTemplate,
      setSelectedDraftTemplate: (template: DraftTemplateOption | null) =>
        setSelectedDraftTemplate(template),
      resetFromTemplateEntry,
      templateName,
      selectedTemplateFileId,
      selectedPromptProfile,
      prompt,
      setPrompt: (value: string) => setPrompt(value),
      promptState,
      setPromptMode: (activeTab: 'idea' | 'aiReviewer') =>
        setPromptState((prev) => ({ ...prev, activeTab })),
      setIdeaText: (ideaText: string) =>
        setPromptState((prev) => ({ ...prev, ideaText })),
      setAiAnswers: (aiAnswers: Record<string, string>) =>
        setPromptState((prev) => ({ ...prev, aiAnswers })),
      hasUpload,
      setHasUpload: (value: boolean) => setHasUpload(value),
      selectedDocument,
      setSelectedDocument: (doc: StartSelectedDocumentInfo | null) =>
        setSelectedDocument(doc),
      referenceFiles,
      setReferenceFiles: persistReferenceFiles,
      isReferenceFilesProcessing,
      setReferenceFilesProcessing: (value: boolean) =>
        setIsReferenceFilesProcessing(value),
      images,
      setImages: (nextImages: ImageItem[]) => setImages(nextImages),
      hasGeneratedSuggestions,
      setHasGeneratedSuggestions: (value: boolean) =>
        setHasGeneratedSuggestions(value),
      theme,
      setTheme: (nextTheme: Theme | undefined) => setTheme(nextTheme),
      language: 'ko' as const,
      exportedProductId,
      setExportedProductId: (id: string | null) => setExportedProductId(id),
      generateStartToken,
      goToVisualSuggestions: () => navigate({ to: VISUAL_SUGGESTIONS_PATH }),
      startGenerate: () => {
        setGenerateStartToken((prev) => prev + 1);
        navigate({ to: GENERATE_PATH });
      },
      resetFlow,
      clearCompletedFlow
    }),
    [
      clearCompletedFlow,
      draftTemplates,
      exportedProductId,
      generateStartToken,
      hasGeneratedSuggestions,
      hasUpload,
      images,
      isReferenceFilesProcessing,
      isDraftTemplatesError,
      isDraftTemplatesLoading,
      navigate,
      persistReferenceFiles,
      prompt,
      promptState,
      referenceFiles,
      refetchDraftTemplates,
      resetFromTemplateEntry,
      resetFlow,
      selectedDocument,
      selectedDraftTemplate,
      selectedPromptProfile,
      selectedTemplateFileId,
      templateName,
      theme
    ]
  );

  return (
    <StartFlowProvider value={contextValue}>
      <StyledStartContainer>
        {currentStep > 1 && (
          <InstantStepper currentStep={currentStep} hideFirstStep />
        )}

        <StyledContentArea
          ref={contentRef}
          style={isTemplateRoute ? { paddingTop: 60 } : undefined}
        >
          <StyledStepContent key={currentPath}>
            <Outlet />
          </StyledStepContent>
        </StyledContentArea>

        {currentStepKey !== 'settings' && (
          <StyledFooter>
            <StyledFooterInner>
              {currentStepKey === 'template' ||
              currentStepKey === 'generate' ? (
                <>
                  <div />
                  <div />
                </>
              ) : currentStepKey === 'visual-suggestions' ||
                currentStepKey === 'upload' ? (
                <>
                  <Button variant="outlined" size="large" onClick={goPrev}>
                    이전
                  </Button>
                  <Button
                    variant="filled"
                    size="large"
                    disabled={!canGoNext()}
                    onClick={handleNextWithValidation}
                  >
                    다음 단계
                  </Button>
                </>
              ) : currentStepKey === 'prompt' ? (
                <>
                  <Button variant="outlined" size="large" onClick={goPrev}>
                    이전
                  </Button>
                  <Flex gap={12}>
                    <Button variant="outlined" size="large" onClick={goNext}>
                      건너뛰기
                    </Button>
                    <Button
                      variant="filled"
                      size="large"
                      disabled={!canGoNext()}
                      onClick={handleNextWithValidation}
                    >
                      다음 단계
                    </Button>
                  </Flex>
                </>
              ) : (
                <>
                  <div />
                  <div />
                </>
              )}
            </StyledFooterInner>
          </StyledFooter>
        )}

        {showImageResetWarning && (
          <StyledModalOverlay onClick={() => setShowImageResetWarning(false)}>
            <StyledModalBox onClick={(event) => event.stopPropagation()}>
              <StyledModalHeader>
                <StyledModalTitle>
                  이전 단계로 이동하시겠습니까?
                </StyledModalTitle>
                <StyledModalClose
                  onClick={() => setShowImageResetWarning(false)}
                >
                  <X size={20} />
                </StyledModalClose>
              </StyledModalHeader>
              <StyledModalDesc>
                이전 단계로 이동하면 입력하신 이미지 프롬프트가 초기화됩니다.
              </StyledModalDesc>
              <StyledModalFooter>
                <StyledBtnOutlined
                  onClick={() => setShowImageResetWarning(false)}
                >
                  취소
                </StyledBtnOutlined>
                <StyledBtnWarning onClick={confirmImageReset}>
                  초기화 후 이동
                </StyledBtnWarning>
              </StyledModalFooter>
            </StyledModalBox>
          </StyledModalOverlay>
        )}

        {showLoadingPopup && (
          <StyledLoadingOverlay>
            <StyledLoadingPopup>
              {loadingError ? (
                <>
                  <div
                    style={{
                      fontSize: 20,
                      fontWeight: 600,
                      marginBottom: 8,
                      letterSpacing: '-0.02em',
                      color: '#25262C'
                    }}
                  >
                    시각 자료 추천에 실패했습니다
                  </div>
                  <div
                    style={{
                      fontSize: 14,
                      color: '#6E7687',
                      lineHeight: 1.6,
                      letterSpacing: '-0.02em',
                      marginBottom: 20
                    }}
                  >
                    네트워크 상태를 확인하고 다시 시도해주세요.
                  </div>
                  <Flex gap={12}>
                    <Button
                      variant="outlined"
                      size="medium"
                      onClick={() => setShowLoadingPopup(false)}
                    >
                      닫기
                    </Button>
                    <Button
                      variant="filled"
                      size="medium"
                      onClick={handleRetry}
                    >
                      다시 시도
                    </Button>
                  </Flex>
                </>
              ) : (
                <>
                  <StyledLoadingSpinnerRing />
                  <div
                    style={{
                      fontSize: 20,
                      fontWeight: 600,
                      marginBottom: 8,
                      letterSpacing: '-0.02em',
                      color: '#25262C'
                    }}
                  >
                    시각 자료를 구성하고 있습니다
                  </div>
                  <div
                    style={{
                      fontSize: 14,
                      color: '#6E7687',
                      lineHeight: 1.6,
                      letterSpacing: '-0.02em'
                    }}
                  >
                    양식과 프롬프트를 분석하여
                    <br />
                    사업계획서에 필요한 이미지 리스트를 생성 중입니다.
                  </div>
                  <StyledLoadingSteps>
                    {LOADING_STEPS.map((label, index) => {
                      const state =
                        index < loadingStep
                          ? 'done'
                          : index === loadingStep
                            ? 'active'
                            : 'pending';

                      return (
                        <StyledLoadingStep key={label}>
                          <StyledLoadingDot $state={state}>
                            {state === 'done' && (
                              <svg
                                width="10"
                                height="10"
                                viewBox="0 0 24 24"
                                fill="none"
                                stroke="white"
                                strokeWidth="3"
                              >
                                <path d="M20 6 9 17l-5-5" />
                              </svg>
                            )}
                          </StyledLoadingDot>
                          <span
                            style={{
                              fontSize: 14,
                              letterSpacing: '-0.02em',
                              color:
                                state === 'pending' ? '#B5B9C4' : '#25262C',
                              fontWeight: state === 'active' ? 500 : 400
                            }}
                          >
                            {state === 'done'
                              ? label.replace(' 중...', '')
                              : label}
                          </span>
                        </StyledLoadingStep>
                      );
                    })}
                  </StyledLoadingSteps>
                </>
              )}
            </StyledLoadingPopup>
          </StyledLoadingOverlay>
        )}
      </StyledStartContainer>
    </StartFlowProvider>
  );
}
