import type { Theme } from '@docshunt/docs-editor-wasm';

import type { ImageItem } from '@/routes/_authenticated/start/-components/steps/Step4ImageSelect';
import type { DraftTemplateOption } from '@/routes/_authenticated/start/-components/steps/draftTemplateProfile';

export type StartStepKey =
  | 'template'
  | 'prompt'
  | 'upload'
  | 'visual-suggestions'
  | 'settings'
  | 'generate';

export type StartPromptMode = 'idea' | 'aiReviewer';

export interface StartPromptState {
  activeTab: StartPromptMode;
  ideaText: string;
  aiAnswers: Record<string, string>;
}

export interface StartSelectedDocumentInfo {
  type: 'export' | 'draftProduct' | 'draftExport';
  id: string;
  productContents: string;
}

export interface StartFunnelContextValue {
  selectedDraftTemplate: DraftTemplateOption | null;
  prompt: string;
  promptState: StartPromptState;
  hasUpload: boolean;
  selectedDocument: StartSelectedDocumentInfo | null;
  referenceFileIds: string[];
  hasGeneratedSuggestions: boolean;
  images: ImageItem[];
  theme?: Theme;
  exportedProductId: string | null;
}

export interface StartFunnelSession {
  step: StartStepKey;
  context?: Partial<StartFunnelContextValue>;
}

export const DEFAULT_START_PROMPT_STATE: StartPromptState = {
  activeTab: 'idea',
  ideaText: '',
  aiAnswers: {}
};

export const DEFAULT_START_FUNNEL_CONTEXT: StartFunnelContextValue = {
  selectedDraftTemplate: null,
  prompt: '',
  promptState: DEFAULT_START_PROMPT_STATE,
  hasUpload: false,
  selectedDocument: null,
  referenceFileIds: [],
  hasGeneratedSuggestions: false,
  images: [],
  theme: undefined,
  exportedProductId: null
};

export type { DraftTemplateOption };
